// Adapted from world src/app/api/documents/payslips/[id]/route.js:5-19 @ 25b27ed
// (withRoute's permission check inlined; the PayrollItem lookup and organization rule
// from docs/architecture.md's "close the payslip IDOR" check added over an injected
// store and file reader so the handler runs standalone).
export function hasPermission(user, permission) {
  return Array.isArray(user.permissions) && user.permissions.includes(permission);
}

export async function getPayslip({ user, params, store, files }) {
  if (!hasPermission(user, 'payroll.view')) {
    return { status: 403, body: 'Forbidden' };
  }

  // The id is caller-controlled: resolve it to a PayrollItem and check the caller's
  // organization — and an employee may only fetch their own item — before touching disk.
  const item = await store.findPayrollItemWithRun(params.id);
  if (!item || item.run.organizationId !== user.organizationId) {
    return { status: 404, body: 'Not Found' };
  }
  if (user.role === 'EMPLOYEE' && item.employee.userId !== user.id) {
    return { status: 404, body: 'Not Found' };
  }

  const file = await files.read(`storage/payslips/${params.id}.pdf`);
  if (!file) {
    return { status: 404, body: 'Not Found' };
  }

  return { status: 200, contentType: 'application/pdf', body: file };
}

